def dump_memdb(self, with_source_contents=True, with_names=True):
        """Dumps a sourcemap in MemDB format into bytes."""
        memdb = {}
        if with_source_contents:
            memdb['sourcesContent'] = self.sources_content
        if with_names:
            memdb['names'] = self.names
        memdb['version'] = self.version
        memdb['sources'] = self.sources
        memdb['mappings'] = self.mappings
        return json.dumps(memdb).encode('utf-8')

