def Recurrent(step_model):
    """Apply a stepwise model over a sequence, maintaining state. For RNNs"""
    def loop(seq, state):
        if len(seq) == 0:
            return state
        else:
            head, *tail = seq
            state = step_model(head, state)
            return loop(tail, state)
    return loop

