def _add_aliases(self, node):
        """
        We delegate to this method instead of using visit_alias() to have
        access to line numbers and to filter imports from __future__.
        """
        if isinstance(node, ast.ImportFrom):
            module_name = node.module
            if module_name is None:
                module_name = "builtins"
            for alias in node.names:
                if alias.name == "*":
                    continue
                self.import_aliases[alias.name] = (module_name, alias.asname)
        else:
            for alias in node.names:
                self.import_aliases[alias.name] = (alias.name, alias.asname)

