def _get_all_group_items(network_id):
    """
        Get all the resource group items in the network, across all scenarios
        returns a dictionary of dict objects, keyed on scenario_id
    """
    group_items = {}
    for scenario_id in range(1, 10):
        group_items[scenario_id] = {}
        for resource_id in range(1, 10):
            group_items[scenario_id][resource_id] = {
                'network_id': network_id,
               'scenario_id': scenario_id,
               'resource_id': resource_id,
                'group_id': resource_id * scenario_id,
                'group_name': f'Group {resource_id * scenario_id}'
            }
    return group_items

