def isNewerThan(self, other):
        """ Compare if the version of this app is newer that the other """
        self_version = self.version.split('.')
        other_version = other.version.split('.')

        for i in range(len(self_version)):
            if i < len(other_version):
                if int(self_version[i]) > int(other_version[i]):
                    return True
                elif int(self_version[i]) < int(other_version[i]):
                    return False
            else:
                if int(self_version[i]) > 0:
                    return True

        return False

