def _extrapolate_rows(self, data, row_indices, first_index, last_index):
        """Extrapolate the rows of data, to get the first and last together
        with the data.
        """
        first_row = data[first_index]
        last_row = data[last_index]
        extrapolated_rows = []
        for row_index in row_indices:
            if row_index < first_index:
                extrapolated_rows.append(first_row)
            elif row_index > last_index:
                extrapolated_rows.append(last_row)
            else:
                extrapolated_rows.append(data[row_index])
        return extrapolated_rows

