mgc_code:
def parse_iterable(self, stream, start, end):
        """
        Sequence ::= SequenceStart WSC SequenceValue? WSC SequenceEnd
        Set := SetStart WSC SequenceValue? WSC SetEnd
        SequenceValue ::= Value (WSC SeparatorSymbol WSC Value)*
        """
        sequence_start = re.compile(rf"\s*{start}\s*")
        sequence_end = re.compile(rf"\s*{end}\s*")
        separator = re.compile(r"\s*,\s*")
        sequence_value = re.compile(rf"\s*{self.value}\s*")
        result = []
        for token in stream:
            if sequence_start.match(token):
                continue
            elif sequence_end.match(token):
                break
            elif separator.match(token):
                continue
            elif sequence_value.match(token):
                result.append(token)
            else:
                raise ValueError("Invalid token")
        return result

