mgc_code:
def node_rank(self):
        """
        Returns the maximum rank for each **topological node** in the 
        ``DictGraph``. The rank of a node is defined as the number of edges 
        between the node and a node which has rank 0. A **topological node** 
        has rank 0 if it has no incoming edges.

        """
        ranks = {}
        for node in self.nodes():
            if self.in_degree(node) == 0:
                ranks[node] = 0
            else:
                ranks[node] = max(ranks.get(neighbor, 0) + 1 for neighbor in self.neighbors(node))
        return ranks

def phred_13_to_18_sed(self, new_path=None, in_place=True):
        """Illumina-1.3 format conversion to Illumina-1.8 format via sed (faster)."""
        if in_place:
            new_path = self.path
        with open(new_path, "w") as new_file:
            subprocess.run(["sed", "s/B/C/g", self.path], stdout=new_file)

