def ReadClientCrashInfo(self, client_id):
    """Reads the latest client crash record for a single client."""
    if not client_id:
        return None
    crash_records = self.db.query(
        "SELECT * FROM crash_records WHERE client_id =?",
        (client_id,)
    )
    if not crash_records:
        return None
    return crash_records[0]

