mgc_code:
def _K(m):
    """ matrix K_m from Wiktorsson2001 """
    K = np.zeros((m+1, m+1))
    for i in range(m+1):
        for j in range(m+1):
            K[i, j] = 1 / (i + j + 1)
    return K

